    @Test
    public void testConstructorInitializesDefaultValues() throws Exception {
        // Act
        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();

        // Assert - Since the fields are likely private, we use reflection to verify the internal state 
        // to ensure the constructor logic actually applied the values as specified.

        // Note: In a real-world scenario, we would use getter methods if available.
        // Given the provided API, we verify the side effects of the constructor.

        Assert.assertNotNull("Optimizer should be instantiated", optimizer);

        // We verify the state via reflection to ensure the constructor logic is covered.
        // This assumes the standard Apache Commons Math field names.

        double maxIterations = getFieldValue(optimizer, "maxIterations");
        double initialStepBoundFactor = getFieldValue(optimizer, "initialStepBoundFactor");
        double costRelativeTolerance = getFieldValue(optimizer, "costRelativeTolerance");
        double parRelativeTolerance = getFieldValue(optimizer, "parRelativeTolerance");
        double orthoTolerance = getFieldValue(optimizer, "orthoTolerance");

        Assert.assertEquals(1000.0, maxIterations, 1e-9);
        Assert.assertEquals(100.0, initialStepBoundFactor, 1e-9);
        Assert.assertEquals(1.0e-10, costRelativeTolerance, 1e-15);
        Assert.assertEquals(1.0e-10, parRelativeTolerance, 1e-15);
        Assert.assertEquals(1.0e-10, orthoTolerance, 1e-15);
    }



    /**
     * Helper method to access private fields for verification purposes.
     */
    private double getFieldValue(Object obj, String fieldName) throws Exception {
        Field field = obj.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        Object value = field.get(obj);
        if (value instanceof Integer) {
            return ((Integer) value).doubleValue();
        }
        return (double) value;
    }
